function UIActivityMidFestivalBossRankRewardDialog:GetRewardListVo()
    local allVos = CfUtils.GetCf(AutoIds.IdSetting6103, "MidFestivalBossRankRewardVo", true)
    ---@type ActivityMidFestivalComponent
    local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityMidFestivalComponent)
    local activityDojo = comp:GetActivityDojo()
    local data = {}
    for i, v in pairs(allVos) do
        if v.activityId == activityDojo.activityContentId then
            table.insert(data,v)
        end
    end
    return data
end

